query:
query Search($search: String!, $cursor: String!, $type: Type, $noMisspell: Boolean) {
  search(
    query: {cursor: $cursor, query: $search, type: $type, noMisspell: $noMisspell}
  ) {
    cursor
    misspell {
      ...FSearchMisspellItem
      __typename
    }
    page {
      ...FSearchItem
      __typename
    }
    __typename
  }
}

fragment FSearchCover on Cover {
  url
  ratio
  backgroundColorHex
  __typename
}

fragment FSearchUser on User {
  name
  uuid
  login
  followersCount
  avatar {
    ...FSearchCover
    __typename
  }
  __typename
}

fragment FSearchTopic on Topic {
  name
  uuid
  totalBook
  slug
  parent {
    slug
    name
    __typename
  }
  __typename
}

fragment FSearchBookPerson on Person {
  uuid
  name
  hidden
  __typename
}

fragment FSearchSeries on Series {
  uuid
  name
  cover {
    ...FSearchCover
    __typename
  }
  items {
    total
    followersCount
    __typename
  }
  authors {
    ...FSearchBookPerson
    __typename
  }
  __typename
}

fragment FSearchPerson on Person {
  name
  uuid
  roles
  worksCount
  author {
    totalBook
    __typename
  }
  narrator {
    totalBook
    __typename
  }
  translator {
    totalBook
    __typename
  }
  avatar {
    ...FSearchCover
    __typename
  }
  __typename
}

fragment FBookSearch on Book {
  initUuid
  name
  cover {
    ...FSearchCover
    __typename
  }
  authors {
    ...FSearchBookPerson
    __typename
  }
  purchaseOffer {
    price
    currency
    __typename
  }
  __typename
}

fragment FBookSearchItem on Book {
  ...FBookSearch
  tags {
    name
    value
    __typename
  }
  __typename
}

fragment FSearchBookProgress on Progress {
  inLibrary
  finished
  progress
  __typename
}

fragment FSearchAvailability on Availability {
  ageRestriction {
    name
    value
    __typename
  }
  __typename
}

fragment FSearchTextBook on TextBook {
  book {
    ...FBookSearchItem
    auditory {
      total
      __typename
    }
    __typename
  }
  progress {
    ...FSearchBookProgress
    __typename
  }
  availability {
    ...FSearchAvailability
    __typename
  }
  __typename
}

fragment FSearchAudioBook on AudioBook {
  book {
    ...FBookSearchItem
    auditory {
      total
      __typename
    }
    __typename
  }
  narrators {
    ...FSearchBookPerson
    __typename
  }
  progress {
    ...FSearchBookProgress
    __typename
  }
  availability {
    ...FSearchAvailability
    __typename
  }
  __typename
}

fragment FSearchComicBook on ComicBook {
  book {
    ...FBookSearchItem
    auditory {
      total
      __typename
    }
    __typename
  }
  progress {
    ...FSearchBookProgress
    __typename
  }
  availability {
    ...FSearchAvailability
    __typename
  }
  __typename
}

fragment FSearchBookshelf on Bookshelf {
  uuid
  name
  followersCount
  cover {
    ...FSearchCover
    __typename
  }
  description
  postsCount
  user {
    uuid
    avatar {
      ...FSearchCover
      __typename
    }
    name
    __typename
  }
  availability {
    ageRestriction {
      value
      __typename
    }
    __typename
  }
  __typename
}

fragment FSearchPublisher on Publisher {
  name
  uuid
  worksCount
  avatar {
    ...FSearchCover
    __typename
  }
  __typename
}

fragment FSearchTextSerial on TextSerial {
  book {
    ...FBookSearchItem
    auditory {
      total
      __typename
    }
    __typename
  }
  episodes {
    total
    __typename
  }
  progress {
    ...FSearchBookProgress
    __typename
  }
  availability {
    ageRestriction {
      name
      value
      __typename
    }
    __typename
  }
  __typename
}

fragment FSearchMisspellItem on MisspellItem {
  correctedText
  correctionType
  __typename
}

fragment FSearchItem on SearchItem {
  ...FSearchUser
  ...FSearchTopic
  ...FSearchSeries
  ...FSearchPerson
  ...FSearchTextBook
  ...FSearchAudioBook
  ...FSearchComicBook
  ...FSearchBookshelf
  ...FSearchPublisher
  ...FSearchTextSerial
  __typename
}
